-- Hosbah: an app's traffic history, aggregated on the agent from Caddy's JSON access log for the
-- app's routed hosts (see internal/traffic and internal/agent's access-log tailer). One row per
-- app per minute (step 60), folded into 15-minute rows (step 900) after 24 h by the same retention
-- job that compacts server_metrics, and dropped after 30 days.
-- unique_visitors counts distinct sha256(ip+user_agent) seen in the bucket — never the raw IP or
-- user agent. top_paths/top_referrers are each a JSON array of up to 10 {"key": "...", "count": n},
-- already ranked by the agent; compaction re-merges and re-ranks them.
ALTER TABLE app_traffic_minutes ADD CONSTRAINT app_traffic_minutes_step_check CHECK (step IN (60, 900));
CREATE UNIQUE INDEX app_traffic_minutes_bucket_key ON app_traffic_minutes (app_id, step, at);
CREATE INDEX app_traffic_minutes_team_at_idx ON app_traffic_minutes (team_id, at);
CREATE INDEX app_traffic_minutes_step_at_idx ON app_traffic_minutes (step, at);
